update pages set contenu = '{"sections":[]}'::jsonb where path = '/secteurs/';
update pages set contenu = jsonb_set(contenu, '{sections}', (contenu->'sections') || '[{"type":"heros","h1":"La maintenance usine, secteur par secteur","mecanisme":"Le technicien qui arrive chez vous a déjà travaillé dans un contexte comparable au vôtre. Même type d''équipements, mêmes règles, mêmes urgences. Une organisation commune, des compétences choisies par secteur.","cta":"Parler à un chargé d''affaires","telephone":"04 78 33 72 05","phraseDelai":"Nous vous rappelons dans l''heure, du lundi au vendredi de 8h00 à 18h30. Astreinte 24/24 et 7/7 en option."},{"type":"chiffres","chiffres":[{"valeur":"+ 120","libelle":"clients industriels, dont plus de 80 réguliers"},{"valeur":"10 %","libelle":"des candidats retenus, entretien technique et comportemental, résultats partagés"},{"valeur":"4","libelle":"agences, Lyon (siège), Montréal, Dubaï, Madrid, taux horaire homogène partout"}]},{"type":"probleme","punchline":"Le prestataire est arrivé lundi. Il a passé trois semaines à comprendre votre procédé avant de toucher une machine.","puces":[{"accroche":"Un bon technicien dans la logistique peut être perdu devant une presse de forge.","texte":"La mécanique est commune, le contexte ne l''est jamais."},{"accroche":"Les règles ne se devinent pas.","texte":"Hygiène alimentaire, BPF, zones ATEX, sûreté : la conformité fait partie du travail, pas du décor."},{"accroche":"Le diagnostic est lent quand le procédé est inconnu.","texte":"Savoir où regarder vaut des heures d''immobilisation."},{"accroche":"Vous payez la montée en compétence du prestataire.","texte":"Et vous la repayez à chaque changement d''intervenant."}]},{"type":"offre","lignes":[{"prestation":{"accroche":"Affectation par expérience du secteur","texte":", jamais au hasard."},"benefice":"Le technicien parle votre procédé dès la première intervention, pas au bout d''un trimestre."},{"prestation":{"accroche":"Préventif dimensionné sur vos heures de fonctionnement réelles","texte":", pas sur un standard constructeur."},"benefice":"Vous entretenez ce qui tourne, au rythme où ça tourne. Le budget suit l''usage."},{"prestation":{"accroche":"Correctif tracé","texte":"diagnostic, pièces, contrôles, dans votre GMAO."},"benefice":"Votre historique machine s''enrichit à chaque passage. Vos audits se préparent sans reconstitution."},{"prestation":{"texte":"**Analyse des récurrences et plan d''amélioration.**"},"benefice":"La panne qui revient trois fois par an finit par disparaître au lieu d''être repayée."},{"prestation":{"accroche":"Spécialistes du groupe accessibles","texte":"automaticiens SIEMENS et Schneider, roboticiens ABB et Fanuc."},"benefice":"Une compétence rare arrive en renfort au lieu de manquer toute l''année."},{"prestation":{"accroche":"Rétrofit et mise en conformité chiffrés","texte":"par notre [bureau d''études](/offres/bureau-etudes/)."},"benefice":"Vous arbitrez entre entretenir et moderniser sur des chiffres, pas sur une intuition."},{"prestation":{"texte":"**Un taux horaire homogène partout en France.**"},"benefice":"Un groupe multi-sites compare ses usines sans corriger les écarts de tarif régional."}],"prose":[{"texte":"Chaque page secteur détaille les équipements couverts et les contraintes propres au terrain : [agroalimentaire](/secteurs/agroalimentaire/), [équipements logistiques](/secteurs/logistique/), [automobile](/secteurs/automobile/), [pharmaceutique](/secteurs/pharmaceutique/), [aéronautique](/secteurs/aeronautique/), [chimie](/secteurs/chimie/), [nucléaire](/secteurs/nucleaire/), [industrie lourde](/secteurs/industrie-lourde/), [industrie métallique](/secteurs/industrie-metallique/), [menuiserie industrielle](/secteurs/menuiserie-industrielle/)."}]},{"type":"deroule","etapes":[{"titre":"Qualification","texte":"un chargé d''affaires écoute votre activité avant de parler solution. Équipements, criticité, contraintes réglementaires, organisation des équipes."},{"titre":"Choix du profil","texte":"nous proposons un technicien dont l''expérience correspond à votre univers. Les résultats de son évaluation technique et comportementale vous sont présentés."},{"titre":"État des lieux","texte":"parc, historique des pannes, criticité de chaque équipement pour la production. On ne planifie rien sans mesure."},{"titre":"Mise en route","texte":"plan de prévention, accueil sécurité, connexion à votre GMAO, prise en main des équipements critiques."},{"titre":"Exécution","texte":"préventif au bon niveau, correctif tracé, appui des spécialistes du groupe quand la panne sort du périmètre du généraliste."},{"titre":"Revue","texte":"disponibilité, récurrence, coût par équipement. Le plan d''action se revoit à intervalle fixe, avec votre responsable maintenance."}]},{"type":"garanties","puces":[{"accroche":"Un intervenant dont l''expérience est vérifiable","texte":"10 % des candidats retenus, évaluation technique et comportementale en entretien, résultats consultables avant que vous décidiez."},{"accroche":"Aucune sous-traitance en cascade","texte":"les techniciens qui entrent dans votre usine sont salariés Migen. Vous savez qui intervient, à quel niveau, et sous quelle responsabilité."},{"accroche":"Un périmètre écrit ligne par ligne","texte":"ce qui est inclus et ce qui ne l''est pas. Pièces majeures, travaux exceptionnels, transport et levage sont chiffrés à part, jamais découverts en cours de mission."}]},{"type":"cta","question":"Besoin d''un technicien qui connaît déjà votre secteur ?","bouton":"Parler à un chargé d''affaires","rappel":"Ou appelez le 04 78 33 72 05, du lundi au vendredi de 8h00 à 18h30. Rappel dans l''heure."}]'::jsonb) where path = '/secteurs/';
update pages set contenu = jsonb_set(contenu, '{sections}', (contenu->'sections') || '[{"type":"preuves","preuves":[{"titre":"Deux techniciens en 3x8 sur des lignes de nutrition infantile, agroalimentaire","texte":"site de Steenvoorde","lienLibelle":"Étude de cas DANONE : lignes de production","lienHref":"/preuves/danone-lignes-de-production/"},{"titre":"18 à 25 techniciens sur plusieurs sites pendant la transition vers l''électrique, automobile","texte":"depuis juin 2023","lienLibelle":"Étude de cas STELLANTIS : sites du Grand Est","lienHref":"/preuves/stellantis-grand-est/"},{"titre":"Préventif d''un centre logistique qui tourne 24 heures sur 24, logistique","texte":"depuis septembre 2022","lienLibelle":"Étude de cas AMAZON : maintien d''un centre logistique","lienHref":"/preuves/amazon-centre-logistique/"},{"titre":"Automaticien SIEMENS affecté au démarrage d''une ligne neuve, matériaux","texte":"près de Lyon","lienLibelle":"Étude de cas MERSEN : nouvelles lignes","lienHref":"/preuves/mersen/"},{"titre":"Électromécanicien habilité risque chimique sur une remise en état de site, traitement des eaux","texte":"depuis février 2026","lienLibelle":"Étude de cas SUEZ : remise en état d''un site","lienHref":"/preuves/suez-remise-en-etat/"},{"titre":"Renfort d''équipes de maintenance sur plusieurs sites de production, confort thermique","texte":"depuis octobre 2024","lienLibelle":"Étude de cas GROUPE ATLANTIC : renfort d''équipes","lienHref":"/preuves/groupe-atlantic/"}]},{"type":"objections","questions":[{"question":"Notre secteur n''est pas dans votre liste. Vous savez faire ?","reponse":"Les pages listées concentrent notre expérience la plus profonde. Nos techniciens interviennent partout où des machines produisent : plasturgie, papier et carton, verre, textile technique, énergie et énergies renouvelables, centres de tri et valorisation. Décrivez votre cas. Nous répondons honnêtement, y compris quand la réponse est non."},{"question":"Comment choisissez-vous le technicien affecté à notre usine ?","reponse":"Par l''expérience d''un environnement comparable d''abord, équipements proches et règles connues. Ensuite par la spécialité dominante de votre parc, mécanique, électrique ou automatisme. Enfin par la capacité à travailler au contact de vos équipes de production, qui se juge en entretien comportemental."},{"question":"Nos machines sont anciennes et sans documentation. C''est bloquant ?","reponse":"Non, c''est le quotidien de l''industrie française : fonctionnement connu d''une seule personne, pièces introuvables. Nous documentons ce que nous découvrons, passage après passage. En quelques visites, l''installation retrouve un dossier technique utilisable par tous."},{"question":"Combien coûte une maintenance industrielle externalisée ?","reponse":"Un taux horaire homogène partout en France, un chiffrage après qualification du besoin, et des formules à coût prévisible pour le préventif. La comparaison utile n''est pas le tarif horaire seul : c''est le coût complet des arrêts que vous subissez aujourd''hui."},{"question":"Nous avons déjà un prestataire. Comment se passe la reprise ?","reponse":"Nous reprenons le périmètre tel qu''il est écrit, avec une phase de recouvrement pendant laquelle le technicien prend en main les équipements et récupère l''historique. Votre contrat en cours court pendant cette préparation. Aucune interruption de service."},{"question":"Couvrez-vous notre région ?","reponse":"Oui, partout en France depuis 4 agences, Lyon (siège), Montréal, Dubaï et Madrid, et des hubs de techniciens dans les grandes villes de France. Chaque agence porte l''astreinte de sa zone, et les renforts se mutualisent entre agences pour les gros arrêts."}]},{"type":"ctaFinal","question":"Besoin de savoir, en un appel, si nous avons l''expérience utile à votre usine ?","bouton":"Trouver le bon technicien pour mon usine","rappel":"ou appelez le 04 78 33 72 05, rappel dans l''heure aux horaires ouvrés."}]'::jsonb) where path = '/secteurs/';
